def _appointment_booking_handle(payload: Dict[str, Any]) -> Dict[str, Any]:
    try:
        from app.actions.appointment_booking import handle as _handle
        result = _handle(payload)
    except Exception as exc:  # Store/runtime refusal is not HTTP 500
        return {"ok": False, "error": f"{type(exc).__name__}: {exc}"}
    if not isinstance(result, dict):
        return {"ok": False, "error": f"handle() returned {type(result).__name__}"}
    return result


@router.post("/appointment_booking")
async def appointment_booking_create(payload: Dict[str, Any], request: Request) -> Dict[str, Any]:
    from app.auth import reject_invalid_payload, require_platform_token
    tenant = require_platform_token(request)
    reject_invalid_payload("appointment_booking", payload)
    CAPABILITY_ID = "appointment_booking"
    placeholder = refusal_for(CAPABILITY_ID)
    if placeholder is not None:
        return JSONResponse(status_code=UNAVAILABLE_STATUS, content=placeholder)
    handle = _appointment_booking_handle
    save = lambda record: store.save("appointment_booking", record, tenant_id=tenant.tenant_id)
    list_all = lambda: store.list_all("appointment_booking", tenant_id=tenant.tenant_id)
    if not isinstance(payload, dict):
        return {"ok": False, "error": "payload must be an object"}
    required_fields = ['reference', 'status', 'patient_name', 'doctor', 'room', 'starts_at']
    for name in required_fields:
        if name not in payload or payload[name] in (None, ''):
            return {"ok": False,
                    "error": "Missing required field: " + name,
                    'rejected_field': name,
                    'rejection_reason': 'missing_required'}
    constraints = {'reference': {'required': True}, 'status': {'allowed_values': ['open', 'in_progress', 'closed'], 'required': True}, 'patient_name': {'required': True}, 'patient_email': {'required': False}, 'patient_phone': {'required': False}, 'doctor': {'allowed_values': ['dr_reed', 'dr_okafor', 'dr_lindqvist'], 'required': True}, 'room': {'allowed_values': ['room_1', 'room_2', 'room_3'], 'required': True}, 'starts_at': {'required': True}, 'duration_minutes': {'min': 5, 'required': False}, 'reason': {'required': False}, 'channel': {'allowed_values': ['email', 'whatsapp', 'mcp'], 'required': False}}
    for name, rules in constraints.items():
        if name not in payload:
            continue
        value = payload[name]
        allowed = rules.get("allowed_values")
        if allowed is not None and value not in allowed:
            return {"ok": False,
                    "error": name + " must be one of: " + ", ".join(allowed),
                    'rejected_field': name,
                    'rejection_reason': 'not_allowed',
                    'allowed_values': list(allowed)}
        low, high = rules.get("min"), rules.get("max")
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            continue
        if low is not None and value < low:
            return {"ok": False, "error": name + " is below the minimum"}
        if high is not None and value > high:
            return {"ok": False, "error": name + " is above the maximum"}
    # A booking may not take a doctor+room+slot another live booking of THIS
    # clinic already holds. Decided here, not in the handler: the tenant is
    # resolved from the caller's token and every row this reads is scoped to
    # it, so a slot taken by another tenant is neither a conflict nor a fact
    # this caller can learn. Re-submitting the same booking is idempotent.
    held_slot = [
        row
        for row in list_all()
        if str(row.get("doctor")) == str(payload.get("doctor"))
        and str(row.get("room")) == str(payload.get("room"))
        and str(row.get("starts_at")) == str(payload.get("starts_at"))
        and str(row.get("reference")) != str(payload.get("reference"))
        and str(row.get("status") or "open").lower() != "closed"
    ]
    if held_slot:
        return {'ok': False,
                'error': 'slot_taken: %s with %s at %s is already booked for %s'
                         % (payload.get("doctor"), payload.get("room"),
                            payload.get("starts_at"), held_slot[0].get("reference")),
                'capability': CAPABILITY_ID}
    result = await run_capability(CAPABILITY_ID, payload, request)
    if isinstance(result, dict) and result.get('status') != 'success':
        return {'ok': False,
                'error': result.get('error_message') or result.get('status'),
                'result': result}
    try:
        stored = save(payload)
    except Exception as exc:
        return {'ok': False,
                'error': f'{type(exc).__name__}: {exc}',
                'capability': CAPABILITY_ID}
    return {'ok': True, "capability": CAPABILITY_ID, "result": result,
            'stored': stored}


@router.get("/appointment_booking")
def appointment_booking_list(request: Request) -> Dict[str, Any]:
    from app.auth import require_platform_token
    tenant = require_platform_token(request)
    # F7: filter/sort/page from the entity's own declared columns.
    # An unrecognised query field is refused rather than ignored --
    # silently dropping ?staus=open returns the whole table and looks
    # like a match.
    CONTROLS = {"limit", "offset", "sort", "order"}
    allowed = set(store.COLUMNS["appointment_booking"]) | CONTROLS
    given = dict(request.query_params)
    unknown = sorted(k for k in given if k not in allowed)
    if unknown:
        return {"ok": False,
                "error": "unknown query field(s): " + ", ".join(unknown)}
    try:
        return store.query("appointment_booking", tenant.tenant_id,
            filters={k: v for k, v in given.items() if k not in CONTROLS},
            sort=given.get("sort"),
            order=given.get("order", "asc"),
            limit=int(given.get("limit", 50)),
            offset=int(given.get("offset", 0)))
    except (store.QueryError, ValueError) as exc:
        return {"ok": False, "error": str(exc)}


