def _imports_formulas(path):
    """The handler imports the product's formulas module (syntax tree)."""
    try:
        tree = ast.parse(path.read_text(encoding="utf-8", errors="replace"))
    except SyntaxError:
        return False
    for node in ast.walk(tree):
        if isinstance(node, ast.Import) and any(a.name.split(".")[-1] == "formulas" for a in node.names):
            return True
        if isinstance(node, ast.ImportFrom):
            if (node.module or "").split(".")[-1] == "formulas" or any(a.name == "formulas" for a in node.names):
                return True
    return False


def _dockerfile_builds(directory):
    """The Dockerfile, read as instructions: the image builds ``directory``
    when a COPY/ADD brings it in (or a WORKDIR enters it) and a RUN follows."""
    path = Path("Dockerfile")
    if not path.is_file():
        return False
    entered = False
    for raw in path.read_text(encoding="utf-8", errors="replace").splitlines():
        line = raw.strip()
        if not line or line[0] == "#":
            continue
        keyword, _, rest = line.partition(" ")
        keyword = keyword.upper()
        args = [a for a in rest.split() if a[:2] != "--"]
        if keyword in ("COPY", "ADD") and any(Path(a).parts[:1] == (directory,) for a in args[:-1]):
            entered = True
        elif keyword == "WORKDIR" and args and directory in Path(args[0]).parts:
            entered = True
        elif keyword == "RUN" and entered:
            return True

"""Handler for capability visit_invoicing.

Authored by the coding agent: the invoice raised for one visit. The charge is
expressed in the platform's canonical finance model, reconciled against the
visit it bills, metered for usage, and held in escrow until it is paid.

Money values are never typed in: currency, country and any tax rate are read
from app.money_settings at the point of use (PLATFORM_CURRENCY /
PLATFORM_COUNTRY / PLATFORM_TAX_RATE, else the customer's declared locale),
and the amount is scaled only by a factor that came from there.

Persistence is route-scoped: the ROUTE's tenant-scoped save writes the
request after SUCCESS; handle() is pure dispatch.
"""

from __future__ import annotations

import os
from typing import Any, Dict, Tuple

from app.dispatch import execute

