CAPABILITY_ID = "visit_invoicing"
ENTITY = 'visit_invoicing'
BLOCK_IDS = ['finance_canonical_model', 'finance_reconciliation', 'billing', 'payment_escrow']
#: Each block's declared default action (from its block.json).
BLOCK_DEFAULT_ACTIONS = {'finance_canonical_model': 'schema', 'billing': 'record_usage'}
CAPABILITY_FIELDS = ['reference', 'status', 'patient_name', 'doctor', 'visit_date', 'amount', 'currency', 'description']
#: The authority label every answer carries: which layer answered.
AUTHORITY_LABEL = 'clinic.billing/visit_invoicing: invoice over finance_canonical_model, finance_reconciliation, billing, payment_escrow (CAD settings from app.money_settings)'

CLINIC_PRINCIPAL = "clinic-desk"


def _text(value: Any, fallback: str = "") -> str:
    return str(value).strip() if value is not None else fallback


def _number(value: Any) -> float:
    try:
        return round(float(value), 2)
    except (TypeError, ValueError):
        return 0.0


def _money_settings() -> Tuple[str, str, float]:
    """(currency, country, tax rate) from the operator's own settings.

    Returns rate 0.0 when no tax rate is configured: an unconfigured rate is
    an untaxed invoice, not a guessed one.
    """
    from app import money_settings

    currency = money_settings.currency()
    country = money_settings.country()
    try:
        rate = float(money_settings.tax_rate())
    except (money_settings.MoneySettingMissing, TypeError, ValueError):
        rate = 0.0
    return currency, country, rate


def _billing_key() -> str:
    return (os.getenv("BILLING_API_KEY") or "local-offline").strip()


def _refused(result: Dict[str, Any]) -> bool:
    if result.get("ok") is False:
        return True
    if str(result.get("status") or "").lower() in ("error", "fail", "failed"):
        return True
    return bool(result.get("error")) and "error_kind" not in result


def _reason(result: Dict[str, Any]) -> str:
    return str(result.get("error") or result.get("status") or result)[:200]

#: Scope of this handler, stated the way a block states its own:
#: what it READS, what it WRITES, and what it must NEVER touch.
SCOPES = {
    "reads": ["caller.input", "block.dispatch", "config.money_settings"],
    "writes": ["caller.output", "payment_escrow.hold"],
    "never": ["network.http.outbound", "store.direct_write", "caller.tenant", "hardcoded_rate"],
}


def handle(payload: Dict[str, Any]) -> Dict[str, Any]:
    record = dict(payload or {})
    missing = [
        name
        for name in ("reference", "patient_name", "amount")
        if record.get(name) in (None, "")
    ]
    if missing:
        return {
            "ok": False,
            "capability": CAPABILITY_ID,
            "error": "missing required invoice field(s): " + ", ".join(missing),
        }

    reference = _text(record.get("reference"))
    charged = _number(record.get("amount"))
    if charged <= 0:
        return {
            "ok": False,
            "capability": CAPABILITY_ID,
            "error": "amount must be greater than zero to raise an invoice",
        }

    try:
        currency, country, tax_rate = _money_settings()
    except Exception as exc:
        return {
            "ok": False,
            "capability": CAPABILITY_ID,
            "error": "money settings unavailable: %s: %s" % (type(exc).__name__, exc),
        }
    tax = round(charged * tax_rate, 2)
    total = round(charged + tax, 2)

    results: Dict[str, Any] = {}
    errors: Dict[str, str] = {}
    notes: Dict[str, str] = {}

    def call(block_id: str, data: Dict[str, Any], action: str, **kwargs: Any) -> Dict[str, Any]:
        try:
            result = execute(block_id, data, action=action, **kwargs)
        except Exception as exc:  # a block refusal is data, never an HTTP 500
            result = {"status": "error", "error": "%s: %s" % (type(exc).__name__, exc)}
        if not isinstance(result, dict):
            result = {"status": "error", "error": "%s returned %s" % (block_id, type(result).__name__)}
        results[block_id] = result
        if _refused(result):
            errors[block_id] = _reason(result)
        return result

    # 1. Express the invoice in the canonical finance model.
    call(
        "finance_canonical_model",
        {"operation": BLOCK_DEFAULT_ACTIONS["finance_canonical_model"], "model_version": "finance_ops.v1"},
        BLOCK_DEFAULT_ACTIONS["finance_canonical_model"],
    )

    # 2. Reconcile the invoice against the visit it bills. A variance is a
    #    business fact to report, not a reason to refuse the invoice.
    period = _text(record.get("visit_date")) or "today"
    left = [{
        "entity_id": CLINIC_PRINCIPAL,
        "account_id": "invoice",
        "period": period,
        "currency": currency,
        "amount": total,
    }]
    right = [{
        "entity_id": CLINIC_PRINCIPAL,
        "account_id": "invoice",
        "period": period,
        "currency": currency,
        "amount": charged,
    }]
    reconciled = call(
        "finance_reconciliation",
        {"left_records": left, "right_records": right, "amount_field": "amount"},
        None,
    )
    status = _text(reconciled.get("reconciliation_status")).lower()
    if status and status != "reconciled":
        notes["reconciliation"] = "variance between invoiced %s and charge %s (%s %s)" % (
            total, charged, currency, country,
        )

    # 3. Meter the invoice event.
    call(
        "billing",
        {"input": {
            "api_key": _billing_key(),
            "user_id": CLINIC_PRINCIPAL,
            "block_id": CAPABILITY_ID,
            "tokens": 1,
        }},
        BLOCK_DEFAULT_ACTIONS["billing"],
    )

    # 4. Hold the invoiced total in escrow until it is settled.
    call(
        "payment_escrow",
        {
            "payment_id": "inv-" + reference,
            "amount": total,
            "currency": currency,
            "payer_id": _text(record.get("patient_name")),
            "payee_id": CLINIC_PRINCIPAL,
        },
        "hold",
    )

    if errors:
        return {
            "ok": False,
            "capability": CAPABILITY_ID,
            "error": "; ".join("%s: %s" % item for item in sorted(errors.items())),
            "results": results,
        }

    return {
        "ok": True,
        "authority": AUTHORITY_LABEL,
        "capability": CAPABILITY_ID,
        "outcome": "invoice_raised",
        "reference": reference,
        "currency": currency,
        "charged": charged,
        "tax": tax,
        "total": total,
        "notes": notes,
        "results": results,
    }

