"""Retrieval over the documents the clinic itself supplies.

The clinic's own material -- procedures, opening hours, doctor notes the
practice chooses to index -- is ingested here and retrieved here. Nothing is
seeded: the corpus is empty until a caller ingests something, which is the
only honest state for a retrieval surface nobody has given sources to yet.

How retrieval works, and its honest limit. The corpus lives in this
platform's own database (``rag_document``, one row per chunk, scoped by the
tenant the token resolves to). A query is scored lexically: the query's terms
are matched against each chunk with an inverse-document-frequency weight, so
a term no chunk contains contributes nothing and a query for something never
ingested returns no content at all. That is real retrieval, not an echo of the
request. It is not semantic: no embedding model is fetched or called -- this
platform makes no outbound call at runtime -- and the vendored kernel's
semantic engine (``app.cerebrum_product_kernel.retrieval_engine``) is wired
to a real embedder in the platform, not here.

Every answer carries the layer it came from, under ``authority``.
"""

from __future__ import annotations

import hashlib
import math
import re
from datetime import datetime, timezone
from typing import Any, Dict, List, Optional

import sqlalchemy as sa
from sqlalchemy.dialects import sqlite as _sqlite_dialect
from fastapi import APIRouter, Request

from app import db as _db
from app.auth import require_platform_token

router = APIRouter(prefix="/v1/rag", tags=["retrieval"])

TABLE = "rag_document"
AUTHORITY = (
    "clinic.documents/rag: lexical retrieval over the tenant's own ingested "
    "sources (no outbound call; empty until documents are ingested)"
)
MAX_CHUNK_CHARS = 1200
DEFAULT_LIMIT = 5
MAX_LIMIT = 20
#: The body fields the brief declares for the document text, plus the ones a
#: caller naturally sends. Any of them is accepted; none is invented.
INGEST_TEXT_FIELDS = ("text", "content", "paragraph", "document", "body")
QUERY_FIELDS = ("q", "query", "question")

_DOCUMENT = sa.table(
    TABLE,
    sa.column("id"),
    sa.column("tenant_id"),
    sa.column("document_id"),
    sa.column("source"),
    sa.column("chunk_index"),
    sa.column("text"),
    sa.column("created_at"),
)
_SQLITE = _sqlite_dialect.dialect(paramstyle="qmark")
_WORD = re.compile(r"[a-z0-9]{2,}")


def _execute(conn: Any, statement: Any) -> Any:
    """Run one Core statement on either backend's connection."""
    if _db.is_postgres():
        return conn.execute(statement)
    compiled = statement.compile(dialect=_SQLITE)
    params = [compiled.params[name] for name in (compiled.positiontup or ())]
    return conn.execute(str(compiled), params)


def _terms(text: str) -> List[str]:
    return _WORD.findall(str(text or "").lower())


def _first_text(payload: Dict[str, Any]) -> str:
    for field in INGEST_TEXT_FIELDS:
        value = payload.get(field)
        if isinstance(value, str) and value.strip():
            return value
    return ""


def _first_query(payload: Dict[str, Any]) -> str:
    for field in QUERY_FIELDS:
        value = payload.get(field)
        if isinstance(value, str) and value.strip():
            return value
    return ""


def _chunks(text: str) -> List[str]:
    """Paragraph chunks, capped so one long document cannot swallow a query."""
    out: List[str] = []
    for block in re.split(r"\n\s*\n", str(text or "")):
        block = block.strip()
        while len(block) > MAX_CHUNK_CHARS:
            out.append(block[:MAX_CHUNK_CHARS])
            block = block[MAX_CHUNK_CHARS:].strip()
        if block:
            out.append(block)
    return out or ([str(text).strip()] if str(text or "").strip() else [])


def _document_id(tenant_id: str, source: str, text: str) -> str:
    digest = hashlib.sha256(
        ("%s|%s|%s" % (tenant_id, source, text)).encode("utf-8")
    ).hexdigest()
    return "doc-" + digest[:20]


def _now() -> str:
    return datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")


def _as_dict(row: Any) -> Dict[str, Any]:
    """A row as a mapping on either backend (Core mapping or sqlite3.Row)."""
    mapping = getattr(row, "_mapping", None)
    return dict(mapping) if mapping is not None else dict(row)


def _rows(tenant_id: str) -> List[Dict[str, Any]]:
    conn = _db.connect()
    try:
        statement = sa.select(_DOCUMENT).where(_DOCUMENT.c.tenant_id == tenant_id)
        return [_as_dict(row) for row in _execute(conn, statement).fetchall()]
    finally:
        conn.close()


def _score(query_terms: List[str], rows: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    """Lexical score per chunk: idf-weighted term overlap, zero is a miss."""
    if not query_terms or not rows:
        return []
    document_frequency: Dict[str, int] = {}
    chunk_terms: List[List[str]] = []
    for row in rows:
        terms = _terms(row.get("text"))
        chunk_terms.append(terms)
        for term in set(terms):
            document_frequency[term] = document_frequency.get(term, 0) + 1
    total = len(rows)
    wanted = set(query_terms)
    scored: List[Dict[str, Any]] = []
    for row, terms in zip(rows, chunk_terms):
        counts: Dict[str, int] = {}
        for term in terms:
            counts[term] = counts.get(term, 0) + 1
        score = 0.0
        for term in wanted:
            if term not in counts:
                continue
            score += (1.0 + math.log(counts[term])) * (
                math.log((1.0 + total) / (1.0 + document_frequency.get(term, 0))) + 1.0
            )
        if score > 0:
            scored.append(
                {
                    "text": row.get("text"),
                    "source": row.get("source"),
                    "document_id": row.get("document_id"),
                    "chunk_index": row.get("chunk_index"),
                    "score": round(score, 6),
                }
            )
    scored.sort(key=lambda item: (-item["score"], str(item.get("document_id"))))
    return scored


@router.post("/ingest")
async def ingest(payload: Dict[str, Any], request: Request) -> Dict[str, Any]:
    """Add one document to this tenant's corpus. Nothing is seeded."""
    tenant = require_platform_token(request)
    body = dict(payload or {})
    text = _first_text(body)
    if not text:
        return {
            "ok": False,
            "error": "no document text: send one of " + ", ".join(INGEST_TEXT_FIELDS),
            "rejected_field": "text",
        }
    source = str(
        body.get("source") or body.get("title") or body.get("name") or "clinic document"
    ).strip()
    document_id = _document_id(tenant.tenant_id, source, text)
    stored = 0
    conn = _db.connect()
    try:
        existing = _execute(
            conn,
            sa.select(_DOCUMENT.c.id).where(
                _DOCUMENT.c.tenant_id == tenant.tenant_id,
                _DOCUMENT.c.document_id == document_id,
            ),
        ).fetchall()
        if existing:
            return {
                "ok": True,
                "authority": AUTHORITY,
                "document_id": document_id,
                "chunks": 0,
                "idempotent": True,
            }
        for index, chunk in enumerate(_chunks(text)):
            _execute(
                conn,
                sa.insert(_DOCUMENT).values(
                    tenant_id=tenant.tenant_id,
                    document_id=document_id,
                    source=source,
                    chunk_index=index,
                    text=chunk,
                    created_at=_now(),
                ),
            )
            stored += 1
        conn.commit()
    finally:
        conn.close()
    return {
        "ok": True,
        "authority": AUTHORITY,
        "document_id": document_id,
        "chunks": stored,
        "source": source,
    }


def _answer(request: Request, payload: Optional[Dict[str, Any]]) -> Dict[str, Any]:
    tenant = require_platform_token(request)
    body = dict(payload or {})
    raw_limit = body.get("limit")
    try:
        limit = int(raw_limit) if raw_limit is not None else DEFAULT_LIMIT
    except (TypeError, ValueError):
        limit = DEFAULT_LIMIT
    limit = max(1, min(limit, MAX_LIMIT))

    query = _first_query(body)
    if not query:
        return {
            "ok": False,
            "error": "no query: send one of " + ", ".join(QUERY_FIELDS),
            "rejected_field": "q",
        }
    rows = _rows(tenant.tenant_id)
    hits = _score(_terms(query), rows)[:limit]
    return {
        "ok": True,
        "authority": AUTHORITY,
        "query": query,
        "results": hits,
        "total": len(hits),
        "corpus_chunks": len(rows),
        "retrieval": "lexical_idf_terms",
    }


@router.get("/query")
def query_get(request: Request, q: str = "") -> Dict[str, Any]:
    return _answer(request, {"q": q})


@router.post("/query")
async def query_post(payload: Dict[str, Any], request: Request) -> Dict[str, Any]:
