@router.get("/appointment_booking/{item_id}")
def appointment_booking_get(item_id: int, request: Request) -> Dict[str, Any]:

"""Handler for capability appointment_booking.

Authored by the coding agent: real booking flow over the vendored Store
blocks -- a slot reservation is checked against the clinic's own slot ledger
(the ``database`` block's offline store), the appointment is validated, listed
for the front desk, announced, and run once more as an orchestrated pipeline.

Persistence is route-scoped (factory-grounded persist envelope): the ROUTE's
tenant-scoped save writes the request after SUCCESS; handle() is pure
dispatch and must not persist directly (Phase 2 §0.2).
"""

from __future__ import annotations

from typing import Any, Dict, List

from app.dispatch import execute

AUTHORED_BY = "codewhale exec"

CAPABILITY_ID = "appointment_booking"
ENTITY = 'appointment_booking'
BLOCK_IDS = ['workflow', 'task_listing', 'notification', 'validation']
#: Each block's declared default action (from its block.json). Blocks are
#: action-dispatched; calling one with no action is answered with an error.
BLOCK_DEFAULT_ACTIONS = {'workflow': 'run', 'task_listing': 'create', 'notification': 'send', 'validation': 'validate_pipeline'}
CAPABILITY_FIELDS = ['reference', 'status', 'patient_name', 'patient_email', 'patient_phone', 'doctor', 'room', 'starts_at', 'duration_minutes', 'reason', 'channel']
#: The authority label every answer carries: which layer answered.
AUTHORITY_LABEL = 'clinic.scheduler/appointment_booking: booking pipeline over workflow, task_listing, notification, validation (local vendored blocks, no outbound call)'

SLOT_TABLE = "appointment_slot"
SLOT_QUERY = "SELECT reference FROM appointment_slot WHERE slot_key = ?"
SLOT_INSERT = "appointment_slot"


def _text(value: Any, fallback: str = "") -> str:
    return str(value).strip() if value is not None else fallback


def _slot_key(record: Dict[str, Any]) -> str:
    """The clinic's reservation key: one doctor, one room, one start."""
    return "|".join(
        (
            _text(record.get("doctor"), "unassigned"),
            _text(record.get("room"), "unassigned"),
            _text(record.get("starts_at"), "unscheduled"),
        )
    )


def _listing(record: Dict[str, Any]) -> Dict[str, Any]:
    """The front-desk task listing for this appointment (task_listing.create)."""
    minutes = record.get("duration_minutes") or 15
    return {
        "title": "Appointment: %s with %s" % (
            _text(record.get("patient_name"), "patient"),
            _text(record.get("doctor"), "doctor"),
        ),
        "description": "Room %s, %s minutes. %s" % (
            _text(record.get("room"), "unassigned"),
            minutes,
            _text(record.get("reason"), "consultation"),
        ),
        "category": "other",
        "location": {"address": "Consulting room " + _text(record.get("room"), "unassigned")},
        "status": "open",
        "listing_id": _text(record.get("reference")) or None,
    }


def _announcement(record: Dict[str, Any]) -> Dict[str, Any]:
    """The booking announcement, delivered in-process (MCP) to the audit tool.

    A delivery provider (SMTP / SendGrid / Slack / webhook) is used when the
    deploy environment has configured one; offline the in-process channel is
    the one that exists, and that is what the Factory's dispatch contract
    means by ``mcp``.
    """
    message = "Appointment booked for %s with %s in room %s at %s" % (
        _text(record.get("patient_name"), "patient"),
        _text(record.get("doctor"), "doctor"),
        _text(record.get("room"), "unassigned"),
        _text(record.get("starts_at"), "the scheduled time"),
    )
    return {
        "channel": "mcp",
        "block": "audit",
        "tool": "audit",
        "message": message,
        "payload": {
            "action": "log",
            "action_name": "appointment.booked",
            "resource_type": "appointment",
            "resource_id": _text(record.get("reference")),
            "status": "open",
            "details": message,
        },
    }


def _pipeline(record: Dict[str, Any]) -> List[Dict[str, Any]]:
    """The same booking as one orchestrated pipeline (workflow.run)."""
    return [
        {
            "block": "validation",
            "action": "validate_pipeline",
            "input": {
                "item": {"id": _text(record.get("reference")), "type": "appointment"},
                "fail_fast": True,
            },
        },
        {
            "block": "task_listing",
            "action": "create",
            "input": _listing(record),
        },
        {
            "block": "notification",
            "action": "send",
            "input": _announcement(record),
        },
    ]


def _refused(result: Dict[str, Any]) -> bool:
    if result.get("ok") is False:
        return True
    status = str(result.get("status") or "").lower()
    if status in ("error", "fail", "failed"):
        return True
    return bool(result.get("error")) and "error_kind" not in result


def _reason(result: Dict[str, Any]) -> str:
    return str(result.get("error") or result.get("status") or result)[:200]

#: Scope of this handler, stated the way a block states its own:
#: what it READS, what it WRITES, and what it must NEVER touch.
SCOPES = {
    "reads": ["caller.input", "block.dispatch", "database.slot_ledger"],
    "writes": ["caller.output", "database.slot_ledger"],
    "never": ["network.http.outbound", "store.direct_write", "caller.tenant"],
}


def handle(payload: Dict[str, Any]) -> Dict[str, Any]:
    record = dict(payload or {})
    missing = [
        name
        for name in ("reference", "patient_name", "doctor", "room", "starts_at")
        if not _text(record.get(name))
    ]
    if missing:
        return {
            "ok": False,
            "capability": CAPABILITY_ID,
            "error": "missing required booking field(s): " + ", ".join(missing),
        }

    results: Dict[str, Any] = {}
    errors: Dict[str, str] = {}
    deferred: Dict[str, str] = {}
    notes: Dict[str, str] = {}

    def call(block_id: str, data: Dict[str, Any], action: str, **kwargs: Any) -> Dict[str, Any]:
        try:
            result = execute(block_id, data, action=action, **kwargs)
        except Exception as exc:  # a block refusal is data, never an HTTP 500
            result = {"status": "error", "error": "%s: %s" % (type(exc).__name__, exc)}
        if not isinstance(result, dict):
            result = {"status": "error", "error": "%s returned %s" % (block_id, type(result).__name__)}
        results[block_id] = result
        if _refused(result):
            errors[block_id] = _reason(result)
        return result

    # 1. The consultation slot this booking claims. The block's ledger is
    #    shared by every tenant of the platform and is therefore NOT the
    #    place a cross-tenant conflict may be decided or disclosed: a row
    #    naming another clinic's booking would leak it. The tenant-scoped
    #    double-booking decision belongs to the route, which knows the
    #    tenant; here the ledger only records this booking's own claim, so a
    #    replayed request is idempotent and the pipeline has a local slot
    #    record. A conflicting claim is reported as `ledger_conflict` without
    #    repeating any other booking's reference.
    slot = _slot_key(record)
    reference = _text(record.get("reference"))
    ledger = call("database", {}, "list_tables")
    held: Dict[str, Any] = {"rows": []}
    if SLOT_TABLE in (ledger.get("tables") or []):
        held = call(
            "database",
            {"sql": SLOT_QUERY, "params": [slot]},
            "query",
        )
    ledger_conflict = any(
        _text(row.get("reference")) not in ("", reference)
        for row in held.get("rows") or []
    )
    if ledger_conflict:
        notes["ledger_conflict"] = "this slot already has a local reservation"

    # 2. Validate the appointment record, then list it for the front desk.
    call(
        "validation",
        {
            "item": {"id": reference, "type": "appointment"},
            "fail_fast": True,
        },
        BLOCK_DEFAULT_ACTIONS["validation"],
    )
    call("task_listing", _listing(record), BLOCK_DEFAULT_ACTIONS["task_listing"])

    # 3. Announce the booking (in-process channel), then run the same booking
    #    as one pipeline so the orchestration surface sees it too.
    call("notification", _announcement(record), BLOCK_DEFAULT_ACTIONS["notification"])
    call(
        "workflow",
        {"steps": _pipeline(record), "stop_on_error": True},
        BLOCK_DEFAULT_ACTIONS["workflow"],
    )

    if errors:
        return {
            "ok": False,
            "capability": CAPABILITY_ID,
            "error": "; ".join("%s: %s" % item for item in sorted(errors.items())),
            "results": results,
            "deferred": deferred,
        }

    # 4. Record the claim only once every block above agreed.
    call(
        "database",
        {"table": SLOT_INSERT, "values": {"slot_key": slot, "reference": reference}},
        "insert",
    )
    if errors:
        return {
            "ok": False,
            "capability": CAPABILITY_ID,
            "error": "; ".join("%s: %s" % item for item in sorted(errors.items())),
            "results": results,
            "deferred": deferred,
        }

    return {
        "ok": True,
        "authority": AUTHORITY_LABEL,
        "capability": CAPABILITY_ID,
        "outcome": "appointment_booked",
        "slot": slot,
        "reference": reference,
        "notes": notes,
        "results": results,
    }

# A booking may not take a doctor+room+slot another live booking of THIS
# clinic already holds. Decided here, not in the handler: the tenant is
# resolved from the caller's token and every row this reads is scoped to
# it, so a slot taken by another tenant is neither a conflict nor a fact
# this caller can learn. Re-submitting the same booking is idempotent.
held_slot = [
    row
    for row in list_all()
    if str(row.get("doctor")) == str(payload.get("doctor"))
    and str(row.get("room")) == str(payload.get("room"))
    and str(row.get("starts_at")) == str(payload.get("starts_at"))
    and str(row.get("reference")) != str(payload.get("reference"))
    and str(row.get("status") or "open").lower() != "closed"
]
if held_slot:
    return {'ok': False,
            'error': 'slot_taken: %s with %s at %s is already booked for %s'
                     % (payload.get("doctor"), payload.get("room"),
                        payload.get("starts_at"), held_slot[0].get("reference")),
            'capability': CAPABILITY_ID}
result = await run_capability(CAPABILITY_ID, payload, request)
if isinstance(result, dict) and result.get('status') != 'success':
    return {'ok': False,
            'error': result.get('error_message') or result.get('status'),
            'result': result}
try:
    stored = save(payload)
except Exception as exc:
    return {'ok': False,
            'error': f'{type(exc).__name__}: {exc}',
            'capability': CAPABILITY_ID}
return {'ok': True, "capability": CAPABILITY_ID, "result": result,
        'stored': stored}

