    driven = _driven(_html())
    need = min(2, len(caps))
    assert len(driven) >= need, (
        "the served UI drives %d of %d capability(ies) (%s): read "
        "/v1/capabilities and build the routes from it"
        % (len(driven), len(caps), ", ".join(driven) or "none")
    )


